parameters.jsCode:
const process = $('Prepare Process Data').item.json;
const ti = $('Normalize Process TI Result').item.json;
const incident = $('Register Process Incident').item.json;

const report = `# SOC Incident Report

Incident ID: ${incident.id}
Incident Type: Malicious Process Execution

## Endpoint

Agent: ${process.agent_name}
Agent ID: ${process.agent_id}

## Process

PID: ${process.pid}
User: ${process.process_user}
Executable: ${process.executable}
Command: ${process.command}

SHA256:
${process.sha256}

## Threat Intelligence

Source: ${ti.source}
Verdict: ${ti.verdict}
Reputation Score: ${ti.reputation_score}

## Risk Assessment

Risk Score: ${incident.risk_score}/100
Criticality: ${incident.criticality}

## Detection

Wazuh Rule: ${process.rule_id}
Wazuh Rule Level: ${process.rule_level}

## Automated Decision

Action: KILL PROCESS
Status: Active Response pending
`;

const fileName = `incident-${incident.id}-malicious-process.md`;

return {
  json: {
    ...$json,
    report_filename: fileName,
    report_text: report
  },
  binary: {
    report: {
      data: Buffer.from(report, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName
    }
  }
};

